-- Esquema vigente de packing_tracker. Incluye hasta la migración 0007.
-- Ejecutar una sola vez sobre una base vacía, como usuario packing:
--   psql -U packing -d packing_tracker -f db/init.sql
-- Este script deja la base en la versión más avanzada.
-- UNIDADES_TRANSPORTE, EXPEDICIONES, LOTES y LOTES_PRODUCTOS quedan vacías.
-- UNIDADES_ESTATUS, UNIDADES_TIPOS y LOTES_TIPOS nacen con su catálogo.
-- No corras las migraciones después. Las unidades de prueba están en db/seed.sql.

CREATE TABLE "UNIDADES_ESTATUS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false
);

CREATE TABLE "UNIDADES_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false
);

CREATE TABLE "LOTES_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "ES_FINAL" boolean NOT NULL DEFAULT false,
  "MIDE_UNIDAD" boolean NOT NULL DEFAULT false,
  "MIDE_LITRO" boolean NOT NULL DEFAULT false,
  "MIDE_KILO" boolean NOT NULL DEFAULT false,
  CONSTRAINT "LOTES_TIPOS_MEDIDA_CHK" CHECK (
    (
      "ES_FINAL" = false
      AND "MIDE_UNIDAD" = false
      AND "MIDE_LITRO" = false
      AND "MIDE_KILO" = false
    )
    OR (
      "ES_FINAL" = true
      AND ("MIDE_UNIDAD" = true OR "MIDE_LITRO" = true OR "MIDE_KILO" = true)
    )
  )
);

CREATE TABLE "LOTES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_TIPO" integer NOT NULL,
  "PADRE_ID" integer,
  "ID_UNIDAD" integer,
  CONSTRAINT "LOTES_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "LOTES_TIPOS" ("ID"),
  CONSTRAINT "LOTES_PADRE_ID_FK"
    FOREIGN KEY ("PADRE_ID") REFERENCES "LOTES" ("ID"),
  CONSTRAINT "LOTES_PADRE_ID_CHK" CHECK (
    "PADRE_ID" IS NULL OR "PADRE_ID" <> "ID"
  )
);

CREATE INDEX "LOTES_ID_TIPO_IDX" ON "LOTES" ("ID_TIPO");

CREATE INDEX "LOTES_PADRE_ID_IDX" ON "LOTES" ("PADRE_ID");

CREATE INDEX "LOTES_ID_UNIDAD_IDX" ON "LOTES" ("ID_UNIDAD");

CREATE TABLE "LOTES_PRODUCTOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_LOTE" integer NOT NULL,
  "ID_PRODUCTO" integer,
  "CLAVE_PRODUCTO" text,
  "CANTIDAD" numeric(14, 3) NOT NULL,
  "UNIDAD_MEDIDA" text NOT NULL,
  CONSTRAINT "LOTES_PRODUCTOS_ID_LOTE_FK"
    FOREIGN KEY ("ID_LOTE") REFERENCES "LOTES" ("ID") ON DELETE CASCADE,
  CONSTRAINT "LOTES_PRODUCTOS_ID_PRODUCTO_CHK" CHECK (
    "ID_PRODUCTO" IS NULL OR "ID_PRODUCTO" > 0
  ),
  CONSTRAINT "LOTES_PRODUCTOS_CLAVE_PRODUCTO_CHK" CHECK (
    "CLAVE_PRODUCTO" IS NULL OR length(btrim("CLAVE_PRODUCTO")) > 0
  ),
  CONSTRAINT "LOTES_PRODUCTOS_REFERENCIA_CHK" CHECK (
    "ID_PRODUCTO" IS NOT NULL OR "CLAVE_PRODUCTO" IS NOT NULL
  ),
  CONSTRAINT "LOTES_PRODUCTOS_CANTIDAD_CHK" CHECK ("CANTIDAD" > 0),
  CONSTRAINT "LOTES_PRODUCTOS_UNIDAD_MEDIDA_CHK" CHECK (
    "UNIDAD_MEDIDA" IN ('unidad', 'litro', 'kilo')
  ),
  CONSTRAINT "LOTES_PRODUCTOS_UNIDAD_ENTERA_CHK" CHECK (
    "UNIDAD_MEDIDA" <> 'unidad' OR "CANTIDAD" = trunc("CANTIDAD")
  )
);

CREATE INDEX "LOTES_PRODUCTOS_ID_LOTE_IDX" ON "LOTES_PRODUCTOS" ("ID_LOTE");

CREATE TABLE "UNIDADES_TRANSPORTE" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "ID_TIPO" integer NOT NULL,
  "PLACAS" text NOT NULL UNIQUE,
  "NUMERO_ECONOMICO" text UNIQUE,
  "MARCA" text,
  "MODELO" text,
  "ANIO" integer,
  "NUMERO_SERIE" text UNIQUE,
  "CAPACIDAD_CARGA_KG" numeric(12, 2),
  "CAPACIDAD_VOLUMEN_M3" numeric(12, 2),
  "ID_ESTATUS" integer NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "UNIDADES_TRANSPORTE_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "UNIDADES_TIPOS" ("ID"),
  CONSTRAINT "UNIDADES_TRANSPORTE_ID_ESTATUS_FK"
    FOREIGN KEY ("ID_ESTATUS") REFERENCES "UNIDADES_ESTATUS" ("ID"),
  CONSTRAINT "UNIDADES_TRANSPORTE_ANIO_CHK" CHECK (
    "ANIO" IS NULL OR "ANIO" BETWEEN 1980 AND 2100
  ),
  CONSTRAINT "UNIDADES_TRANSPORTE_CAPACIDAD_KG_CHK" CHECK (
    "CAPACIDAD_CARGA_KG" IS NULL OR "CAPACIDAD_CARGA_KG" >= 0
  ),
  CONSTRAINT "UNIDADES_TRANSPORTE_CAPACIDAD_M3_CHK" CHECK (
    "CAPACIDAD_VOLUMEN_M3" IS NULL OR "CAPACIDAD_VOLUMEN_M3" >= 0
  )
);

CREATE INDEX "UNIDADES_TRANSPORTE_ID_TIPO_IDX" ON "UNIDADES_TRANSPORTE" ("ID_TIPO");

CREATE INDEX "UNIDADES_TRANSPORTE_ID_ESTATUS_IDX" ON "UNIDADES_TRANSPORTE" ("ID_ESTATUS");

ALTER TABLE "LOTES"
  ADD CONSTRAINT "LOTES_ID_UNIDAD_FK"
  FOREIGN KEY ("ID_UNIDAD") REFERENCES "UNIDADES_TRANSPORTE" ("ID");

CREATE TABLE "EXPEDICIONES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_UNIDAD" integer NOT NULL,
  "FECHA_CIERRE" timestamptz,
  "ID_UBICACION_SALIDA" integer,
  "CLAVE_UBICACION_SALIDA" text,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "EXPEDICIONES_ID_UNIDAD_FK"
    FOREIGN KEY ("ID_UNIDAD") REFERENCES "UNIDADES_TRANSPORTE" ("ID"),
  CONSTRAINT "EXPEDICIONES_FECHA_CIERRE_CHK" CHECK (
    "FECHA_CIERRE" IS NULL OR "FECHA_CIERRE" >= "CREADO_EN"
  ),
  CONSTRAINT "EXPEDICIONES_ID_UBICACION_SALIDA_CHK" CHECK (
    "ID_UBICACION_SALIDA" IS NULL OR "ID_UBICACION_SALIDA" > 0
  ),
  CONSTRAINT "EXPEDICIONES_CLAVE_UBICACION_SALIDA_CHK" CHECK (
    "CLAVE_UBICACION_SALIDA" IS NULL OR length(btrim("CLAVE_UBICACION_SALIDA")) > 0
  )
);

CREATE INDEX "EXPEDICIONES_ID_UNIDAD_IDX" ON "EXPEDICIONES" ("ID_UNIDAD");

CREATE UNIQUE INDEX "EXPEDICIONES_UNIDAD_ABIERTA_UQ"
  ON "EXPEDICIONES" ("ID_UNIDAD")
  WHERE "FECHA_CIERRE" IS NULL;

CREATE OR REPLACE FUNCTION lotes_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  tipo_final boolean;
  padre_final boolean;
BEGIN
  SELECT "ES_FINAL" INTO tipo_final
  FROM "LOTES_TIPOS"
  WHERE "ID" = NEW."ID_TIPO";

  IF tipo_final IS NULL THEN
    RAISE EXCEPTION 'tipo de lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF tipo_final THEN
    IF NEW."ID_UNIDAD" IS NOT NULL THEN
      RAISE EXCEPTION 'un lote final no se embarca en la unidad' USING ERRCODE = '23514';
    END IF;

    IF NEW."PADRE_ID" IS NOT NULL THEN
      SELECT tipo."ES_FINAL" INTO padre_final
      FROM "LOTES" AS padre
      JOIN "LOTES_TIPOS" AS tipo ON tipo."ID" = padre."ID_TIPO"
      WHERE padre."ID" = NEW."PADRE_ID";

      IF padre_final IS NULL THEN
        RAISE EXCEPTION 'lote padre inexistente' USING ERRCODE = '23503';
      END IF;

      IF padre_final THEN
        RAISE EXCEPTION 'una categoria final no contiene lotes' USING ERRCODE = '23514';
      END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW."ID_TIPO" IS DISTINCT FROM OLD."ID_TIPO" THEN
      IF EXISTS (SELECT 1 FROM "LOTES" WHERE "PADRE_ID" = NEW."ID") THEN
        RAISE EXCEPTION 'una categoria final no contiene lotes' USING ERRCODE = '23514';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM "LOTES_PRODUCTOS" AS producto
        JOIN "LOTES_TIPOS" AS tipo ON tipo."ID" = NEW."ID_TIPO"
        WHERE producto."ID_LOTE" = NEW."ID"
          AND NOT (
            (producto."UNIDAD_MEDIDA" = 'unidad' AND tipo."MIDE_UNIDAD")
            OR (producto."UNIDAD_MEDIDA" = 'litro' AND tipo."MIDE_LITRO")
            OR (producto."UNIDAD_MEDIDA" = 'kilo' AND tipo."MIDE_KILO")
          )
      ) THEN
        RAISE EXCEPTION 'la medida del producto no corresponde al tipo de lote' USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSE
    IF NEW."PADRE_ID" IS NOT NULL THEN
      RAISE EXCEPTION 'solo un lote final puede ir dentro de otro lote' USING ERRCODE = '23514';
    END IF;

    IF EXISTS (SELECT 1 FROM "LOTES_PRODUCTOS" WHERE "ID_LOTE" = NEW."ID") THEN
      RAISE EXCEPTION 'un lote que no es final no contiene productos' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lotes_productos_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  es_final boolean;
  mide_unidad boolean;
  mide_litro boolean;
  mide_kilo boolean;
BEGIN
  SELECT tipo."ES_FINAL", tipo."MIDE_UNIDAD", tipo."MIDE_LITRO", tipo."MIDE_KILO"
  INTO es_final, mide_unidad, mide_litro, mide_kilo
  FROM "LOTES" AS lote
  JOIN "LOTES_TIPOS" AS tipo ON tipo."ID" = lote."ID_TIPO"
  WHERE lote."ID" = NEW."ID_LOTE";

  IF es_final IS NULL THEN
    RAISE EXCEPTION 'lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF NOT es_final THEN
    RAISE EXCEPTION 'solo un lote final contiene productos' USING ERRCODE = '23514';
  END IF;

  IF NOT (
    (NEW."UNIDAD_MEDIDA" = 'unidad' AND mide_unidad)
    OR (NEW."UNIDAD_MEDIDA" = 'litro' AND mide_litro)
    OR (NEW."UNIDAD_MEDIDA" = 'kilo' AND mide_kilo)
  ) THEN
    RAISE EXCEPTION 'la medida del producto no corresponde al tipo de lote' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lotes_tipos_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT NEW."ES_FINAL" AND EXISTS (
    SELECT 1
    FROM "LOTES" AS lote
    JOIN "LOTES_PRODUCTOS" AS producto ON producto."ID_LOTE" = lote."ID"
    WHERE lote."ID_TIPO" = NEW."ID"
  ) THEN
    RAISE EXCEPTION 'el tipo tiene productos y debe seguir siendo final' USING ERRCODE = '23514';
  END IF;

  IF NEW."ES_FINAL" AND EXISTS (
    SELECT 1
    FROM "LOTES" AS hijo
    JOIN "LOTES" AS padre ON padre."ID" = hijo."PADRE_ID"
    WHERE padre."ID_TIPO" = NEW."ID"
  ) THEN
    RAISE EXCEPTION 'el tipo contiene lotes y no puede ser final' USING ERRCODE = '23514';
  END IF;

  IF NOT NEW."ES_FINAL" AND EXISTS (
    SELECT 1 FROM "LOTES"
    WHERE "ID_TIPO" = NEW."ID" AND "PADRE_ID" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'un tipo no final no puede estar dentro de otro lote' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM "LOTES" AS lote
    JOIN "LOTES_PRODUCTOS" AS producto ON producto."ID_LOTE" = lote."ID"
    WHERE lote."ID_TIPO" = NEW."ID"
      AND NOT (
        (producto."UNIDAD_MEDIDA" = 'unidad' AND NEW."MIDE_UNIDAD")
        OR (producto."UNIDAD_MEDIDA" = 'litro' AND NEW."MIDE_LITRO")
        OR (producto."UNIDAD_MEDIDA" = 'kilo' AND NEW."MIDE_KILO")
      )
  ) THEN
    RAISE EXCEPTION 'hay productos con una medida que el tipo ya no permite' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "LOTES_JERARQUIA_TRG"
  BEFORE INSERT OR UPDATE ON "LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION lotes_validar();

CREATE TRIGGER "LOTES_PRODUCTOS_MEDIDA_TRG"
  BEFORE INSERT OR UPDATE ON "LOTES_PRODUCTOS"
  FOR EACH ROW
  EXECUTE FUNCTION lotes_productos_validar();

CREATE TRIGGER "LOTES_TIPOS_USO_TRG"
  BEFORE UPDATE ON "LOTES_TIPOS"
  FOR EACH ROW
  EXECUTE FUNCTION lotes_tipos_validar();

